function updateLabels(){for(const l of labels){let pos=l.position.clone();if(l.kind==='actor'){const a=project.actors.find(a=>a.id===l.id),g=actorMeshes.get(l.id);pos=g.position.clone();pos.y+=a.height+.4;l.el.classList.toggle('selected',selected===l.id);}pos.project(observer);const obj=[...project.actors,...project.rooms].find(o=>o.id===l.id);l.el.style.display=view==='camera'||obj?.visible===false||pos.z>1||pos.z< -1?'none':'';l.el.style.left=`${(pos.x*.5+.5)*$('#viewport').clientWidth}px`;l.el.style.top=`${(-pos.y*.5+.5)*$('#viewport').clientHeight}px`;}}
